import{_ as o,o as a,c as t,N as s}from"./chunks/framework.11ad0a06.js";const h=JSON.parse('{"title":"FAQ","description":"","frontmatter":{"sidebarDepth":2,"collapsable":false},"headers":[],"relativePath":"en/question/index.md","lastUpdated":1795525255000}'),n={name:"en/question/index.md"};function r(i,e,c,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="_1-error-fetching-sub-app-resources" tabindex="-1">1. Error Fetching Sub-app Resources <a class="header-anchor" href="#_1-error-fetching-sub-app-resources" aria-label="Permalink to &quot;1. Error Fetching Sub-app Resources&quot;">​</a></h2><p>Error message: <code>Access to fetch at *** from origin *** has been blocked by CORS policy: No &#39;Access-Control-Allow-Origin&#39;</code></p><p><strong>Cause:</strong> The sub-app server does not allow cross-origin requests, or the resource request requires cookies that are not being sent.</p><p><strong>Solution:</strong></p><ol><li><p>If the issue is missing CORS headers, see <a href="/doc/en/guide/start.html#prerequisites">Prerequisites</a>.</p></li><li><p>If the issue is missing cookies (commonly seen when requests return <code>302</code> redirects to a login page), pass a custom <a href="/doc/en/api/startApp.html#fetch">fetch</a> with <code>credentials: &quot;include&quot;</code> so cookies are attached.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>When <code>credentials</code> is set to <code>&quot;include&quot;</code>, the server cannot return <code>Access-Control-Allow-Origin: *</code> (see <a href="https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS#credentialed_requests_and_wildcards" target="_blank" rel="noreferrer">MDN: Credentialed requests and wildcards</a>). Echo the request origin explicitly on the server instead:</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#BABED8;">ctx</span><span style="color:#89DDFF;">.</span><span style="color:#82AAFF;">set</span><span style="color:#BABED8;">(</span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">Access-Control-Allow-Origin</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#BABED8;"> ctx</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">headers</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">origin)</span><span style="color:#89DDFF;">;</span></span>
<span class="line"></span></code></pre></div></div><h2 id="_2-third-party-package-imported-but-throws-error-at-runtime" tabindex="-1">2. Third-Party Package Imported but Throws Error at Runtime <a class="header-anchor" href="#_2-third-party-package-imported-but-throws-error-at-runtime" aria-label="Permalink to &quot;2. Third-Party Package Imported but Throws Error at Runtime&quot;">​</a></h2><p><strong>Cause:</strong> Normally, top-level scripts execute in the global scope so variables declared with <code>var xxx</code> attach directly to <code>window</code>. However, Wujie wraps sub-app scripts in a closure in order to proxy <code>location</code>. As a result, <code>var xxx</code> stays scoped inside that closure rather than attaching to <code>window</code>, and asynchronous chunks executed in another closure cannot read it.</p><p><strong>Solution:</strong></p><ol><li><p>Explicitly attach the global variable to <code>window</code> (e.g., <code>window.xxx = ...</code>), or configure Webpack&#39;s <a href="https://webpack.js.org/configuration/output/#outputlibrarytarget" target="_blank" rel="noreferrer"><code>output.libraryTarget</code></a> to <code>&quot;window&quot;</code>.</p></li><li><p>If you cannot modify the third-party package, use the <a href="/doc/en/guide/plugin.html#js-loader">js-loader plugin</a> to rewrite <code>xxx=</code> to <code>window.xxx=</code> at runtime.</p></li></ol><h2 id="_3-sub-app-custom-fonts-do-not-take-effect" tabindex="-1">3. Sub-app Custom Fonts Do Not Take Effect <a class="header-anchor" href="#_3-sub-app-custom-fonts-do-not-take-effect" aria-label="Permalink to &quot;3. Sub-app Custom Fonts Do Not Take Effect&quot;">​</a></h2><p><strong>Cause:</strong> <code>@font-face</code> rules declared inside Shadow DOM are not loaded by browsers (see <a href="https://github.com/mdn/interactive-examples/issues/887" target="_blank" rel="noreferrer">mdn/interactive-examples#887</a>).</p><p><strong>Handled by Wujie:</strong> Wujie automatically hoists sub-app <code>@font-face</code> rules outside the Shadow DOM. Just ensure custom font family names do not collide between the main app and sub-apps to avoid overrides.</p><h2 id="_4-popover-dropdown-positioning-is-incorrect" tabindex="-1">4. Popover / Dropdown Positioning Is Incorrect <a class="header-anchor" href="#_4-popover-dropdown-positioning-is-incorrect" aria-label="Permalink to &quot;4. Popover / Dropdown Positioning Is Incorrect&quot;">​</a></h2><p><strong>Cause:</strong> Libraries such as <code>element-plus</code> use <code>popper.js</code> v2, which walks ancestor elements up to <code>window.visualViewport</code> to compute offsets. Because a sub-app&#39;s DOM is mounted inside <code>shadowRoot</code>, scroll offsets relative to <code>window.visualViewport</code> are miscalculated.</p><p><strong>Solution:</strong> Set <code>position: relative</code> on the sub-app&#39;s <code>body</code>.</p><h2 id="_5-e-target-becomes-wujie-app-in-async-event-handlers" tabindex="-1">5. e.target Becomes wujie-app in Async Event Handlers <a class="header-anchor" href="#_5-e-target-becomes-wujie-app-in-async-event-handlers" aria-label="Permalink to &quot;5. e.target Becomes wujie-app in Async Event Handlers&quot;">​</a></h2><p><strong>Cause:</strong> This is standard browser Shadow DOM event retargeting behavior (see <a href="https://stackoverflow.com/questions/63607966/event-target-changed-in-settimeout-in-shadow-dom" target="_blank" rel="noreferrer">Stack Overflow</a>).</p><p><strong>Solution:</strong> Resolve the real target inside asynchronous handlers using: <code>(e.target.shadowRoot &amp;&amp; e.composed) ? (e.composedPath()[0] || e.target) : e.target</code></p><h2 id="_6-relative-urls-inside-css-resolve-against-the-main-app-domain" tabindex="-1">6. Relative URLs Inside CSS Resolve Against the Main App Domain <a class="header-anchor" href="#_6-relative-urls-inside-css-resolve-against-the-main-app-domain" aria-label="Permalink to &quot;6. Relative URLs Inside CSS Resolve Against the Main App Domain&quot;">​</a></h2><p><strong>Handled by Wujie:</strong> Wujie automatically rewrites relative URLs in <code>&lt;style&gt;</code> tags and external CSS files into absolute URLs based on the sub-app origin.</p><h2 id="_7-error-loading-remote-modules-with-module-federation" tabindex="-1">7. Error Loading Remote Modules with Module Federation <a class="header-anchor" href="#_7-error-loading-remote-modules-with-module-federation" aria-label="Permalink to &quot;7. Error Loading Remote Modules with Module Federation&quot;">​</a></h2><p><strong>Cause:</strong> Same as <a href="#_2-third-party-package-imported-but-throws-error-at-runtime">FAQ #2</a> — closure-wrapped script execution prevents global variables declared in one script from being visible in another.</p><p><strong>Solution:</strong> Set <code>library.type</code> to <code>&quot;window&quot;</code> in <code>ModuleFederationPlugin</code>:</p><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#FFCB6B;">library</span><span style="color:#89DDFF;">:</span><span style="color:#BABED8;"> </span><span style="color:#89DDFF;">{</span><span style="color:#F07178;"> </span><span style="color:#FFCB6B;">type</span><span style="color:#89DDFF;">:</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">window</span><span style="color:#89DDFF;">&quot;</span><span style="color:#89DDFF;">,</span><span style="color:#F07178;"> </span><span style="color:#FFCB6B;">name</span><span style="color:#89DDFF;">:</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">&quot;</span><span style="color:#C3E88D;">same-as-plugin-name</span><span style="color:#89DDFF;">&quot;</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">}</span></span>
<span class="line"></span></code></pre></div><h2 id="_8-sub-app-iframe-loads-and-executes-main-app-assets-during-initialization" tabindex="-1">8. Sub-app iframe Loads and Executes Main App Assets During Initialization <a class="header-anchor" href="#_8-sub-app-iframe-loads-and-executes-main-app-assets-during-initialization" aria-label="Permalink to &quot;8. Sub-app iframe Loads and Executes Main App Assets During Initialization&quot;">​</a></h2><p><strong>Cause:</strong> See <a href="https://github.com/Tencent/wujie/issues/54" target="_blank" rel="noreferrer">Tencent/wujie#54</a>.</p><p><strong>Solution:</strong></p><ul><li>Serve an empty endpoint on the main app&#39;s origin (for example, <code>https://host/empty</code> returning an empty 200 response) and pass <a href="/doc/en/api/startApp.html#attrs">attrs</a> as <code>{ src: &quot;https://host/empty&quot; }</code> so the sandbox iframe loads that empty URL.</li><li>Alternatively, place <code>&lt;script&gt;if (window.parent !== window) { window.stop(); }&lt;/script&gt;</code> as the first element inside the main app&#39;s <code>&lt;head&gt;</code> to prevent main app scripts from running inside the sandbox iframe.</li></ul><h2 id="_9-sub-app-window-is-a-proxy-—-how-to-get-the-real-window-object" tabindex="-1">9. Sub-app window Is a Proxy — How to Get the Real window Object <a class="header-anchor" href="#_9-sub-app-window-is-a-proxy-—-how-to-get-the-real-window-object" aria-label="Permalink to &quot;9. Sub-app window Is a Proxy — How to Get the Real window Object&quot;">​</a></h2><p><strong>Cause:</strong> See <a href="https://github.com/Tencent/wujie/issues/63" target="_blank" rel="noreferrer">Tencent/wujie#63</a> for why Wujie proxies <code>window</code>.</p><p><strong>Solution:</strong></p><ul><li>Use <code>window.__WUJIE_RAW_WINDOW__</code> to access the native unproxied <code>window</code> object. See <a href="/doc/en/guide/variable.html#wujie-raw-window">Global Variables</a>.</li></ul><h2 id="_10-domexception-blocked-a-frame-with-origin-from-accessing-a-cross-origin-frame" tabindex="-1">10. DOMException: Blocked a frame with origin from accessing a cross-origin frame <a class="header-anchor" href="#_10-domexception-blocked-a-frame-with-origin-from-accessing-a-cross-origin-frame" aria-label="Permalink to &quot;10. DOMException: Blocked a frame with origin from accessing a cross-origin frame&quot;">​</a></h2><p><strong>Possible Causes:</strong> The sub-app&#39;s iframe sandbox has been navigated away or replaced. Three common causes:</p><ol><li>The sub-app runs inside an iframe whose <code>src</code> is the main app&#39;s <code>host</code>, and that URL triggers a redirect (such as a <code>302</code> to a cross-origin SSO login page), replacing the sandbox.</li><li>The sub-app is built with <code>Vite</code> and assigns to <code>window.location.href</code>, navigating the iframe away.</li><li>A script configured in <a href="/doc/en/guide/plugin.html#js-ignores">jsIgnores</a> assigns to <code>window.location.href</code>.</li></ol><p><strong>Solution:</strong></p><ol><li>Provide a non-redirecting empty path on the main app&#39;s origin (such as <code>https://host/empty</code>) and set <a href="/doc/en/api/startApp.html#attrs">attrs</a> to <code>{ src: &quot;https://host/empty&quot; }</code>.</li><li>In <code>Vite</code> sub-apps, use <code>window.$wujie.location</code> for all <code>location</code> operations.</li><li>In scripts listed under <code>jsIgnores</code>, use <code>window.$wujie.location</code> for all <code>location</code> operations.</li></ol><h2 id="_11-sub-app-relative-asset-urls-request-the-main-app-domain" tabindex="-1">11. Sub-app Relative Asset URLs Request the Main App Domain <a class="header-anchor" href="#_11-sub-app-relative-asset-urls-request-the-main-app-domain" aria-label="Permalink to &quot;11. Sub-app Relative Asset URLs Request the Main App Domain&quot;">​</a></h2><p><strong>Cause:</strong> In standard (non-degrade) mode, the sub-app&#39;s DOM is mounted inside the main app document&#39;s <code>shadowRoot</code>, so relative URLs on elements like images and videos resolve against the main app&#39;s URL instead of the sub-app&#39;s.</p><p><strong>Handled by Wujie:</strong> Relative URLs on the following element attributes are automatically resolved to the sub-app&#39;s origin — whether written in HTML templates or set dynamically via <code>setAttribute</code>, property assignment (e.g., <code>img.src = ...</code>), or <code>innerHTML</code> (including <code>v-html</code>):</p><table><thead><tr><th>Element</th><th>Attribute</th></tr></thead><tbody><tr><td><code>img</code>, <code>source</code></td><td><code>src</code>, <code>srcset</code></td></tr><tr><td><code>video</code></td><td><code>src</code>, <code>poster</code></td></tr><tr><td><code>audio</code>, <code>track</code>, <code>iframe</code>, <code>embed</code></td><td><code>src</code></td></tr><tr><td><code>object</code></td><td><code>data</code></td></tr><tr><td><code>a</code>, <code>link</code></td><td><code>href</code></td></tr><tr><td><code>script</code></td><td><code>src</code></td></tr><tr><td>SVG <code>image</code></td><td><code>href</code>, <code>xlink:href</code></td></tr></tbody></table><p>Fragment-only URLs starting with <code>#</code> are left untouched. Versions <code>2.1.1</code> and earlier only covered <code>src</code> / <code>href</code> on <code>img</code>, <code>a</code>, <code>source</code>, <code>link</code>, <code>script</code>, <code>video</code>, and <code>audio</code> and did not rewrite <code>innerHTML</code>; upgrading covers the full table above.</p><p><strong>Still requires manual handling:</strong> <code>url()</code> inside inline <code>style</code> attributes (for <code>&lt;style&gt;</code> blocks and external CSS files, see <a href="#_6-relative-urls-inside-css-resolve-against-the-main-app-domain">FAQ #6</a>), as well as HTML inserted via <code>insertAdjacentHTML</code>, <code>outerHTML</code>, or similar APIs.</p><p><strong>Recommended Best Practice:</strong> Configure your build so asset URLs do not depend on document base-URL resolution, using either approach below:</p><ol><li>Use absolute asset URLs with the sub-app origin. For Webpack sub-apps, import <code>./config</code> at the very top of your <code>main</code> entry file with the snippet below; for Vite sub-apps, set <code>base</code> to the full sub-app origin URL:</li></ol><div class="language-javascript"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki material-theme-palenight"><code><span class="line"><span style="color:#89DDFF;font-style:italic;">if</span><span style="color:#BABED8;"> (window</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">__POWERED_BY_WUJIE__) </span><span style="color:#89DDFF;">{</span></span>
<span class="line"><span style="color:#89DDFF;">  </span><span style="color:#676E95;font-style:italic;">// eslint-disable-next-line</span></span>
<span class="line"><span style="color:#F07178;">  </span><span style="color:#BABED8;">window</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">__webpack_public_path__</span><span style="color:#F07178;"> </span><span style="color:#89DDFF;">=</span><span style="color:#F07178;"> </span><span style="color:#BABED8;">window</span><span style="color:#89DDFF;">.</span><span style="color:#BABED8;">__WUJIE_PUBLIC_PATH__</span><span style="color:#89DDFF;">;</span></span>
<span class="line"><span style="color:#89DDFF;">}</span></span>
<span class="line"></span></code></pre></div><ol start="2"><li>Configure a same-origin reverse proxy on the main app to forward sub-app asset paths to the sub-app server (ensure asset path prefixes do not collide with the main app).</li></ol><h2 id="_12-vite-4-sub-app-loses-styles-when-switching" tabindex="-1">12. Vite 4 Sub-app Loses Styles When Switching <a class="header-anchor" href="#_12-vite-4-sub-app-loses-styles-when-switching" aria-label="Permalink to &quot;12. Vite 4 Sub-app Loses Styles When Switching&quot;">​</a></h2><p>See <a href="https://github.com/Tencent/wujie/issues/434#issuecomment-1614089196" target="_blank" rel="noreferrer">Tencent/wujie#434</a> for the root cause and workaround.</p>`,51)])])}const g=o(n,[["render",r]]);export{h as __pageData,g as default};
